SourceCode.Declaration:
/// <summary>
/// Data contract for the custom scheduled batch posting of recurring free text invoices.
///
/// Exposes a query (backed by <c>METCustRecurrenceInvoiceBatchPost</c>) that allows the user
/// to filter <c>CustRecurrenceInvoiceGroup</c> records by generation date and invoice date
/// via the "Records to include" filter in the batch dialog.
///
/// Also carries groupRecId, startBundle, and endBundle as plain RecId scalars for use
/// by child batch tasks. Plain scalars survive SysOperation XML serialisation across
/// batch session boundaries reliably. Table-buffer DataMembers lose their RecId on
/// deserialisation, which causes the "record has never been selected" error.
/// </summary>
[DataContractAttribute, SysOperationAlwaysInitializeAttribute]
class METCustRecurrenceInvoiceBatchPostContract
{
    str     packedQuery;
    RecId   groupRecId;
    RecId   startBundle;
    RecId   endBundle;

}

Method.Source:
[
    DataMemberAttribute,
    AifQueryTypeAttribute('_packedQuery', queryStr(METCustRecurrenceInvoiceBatchPost))
]
public str parmQuery(str _packedQuery = packedQuery)
{
    packedQuery = _packedQuery;
    return packedQuery;
}

/// <summary>
/// Gets or sets the RecId of the CustRecurrenceInvoiceGroup to post.
/// Stored as a plain scalar so it survives SysOperation batch serialisation reliably.
/// Hidden from the dialog — used only for internal child batch task communication.
/// </summary>
[
    DataMemberAttribute,
    SysOperationControlVisibility(false)
]
public RecId parmGroupRecId(RecId _groupRecId = groupRecId)
{
    groupRecId = _groupRecId;
    return groupRecId;
}

/// <summary>
/// Gets or sets the RecId of the first RecurrenceInvoice in the bundle.
/// Hidden from the dialog — used only for internal child batch task communication.
/// </summary>
[
    DataMemberAttribute,
    SysOperationControlVisibility(false)
]
public RecId parmStartBundle(RecId _startBundle = startBundle)
{
    startBundle = _startBundle;
    return startBundle;
}

/// <summary>
/// Gets or sets the RecId of the last RecurrenceInvoice in the bundle.
/// Hidden from the dialog — used only for internal child batch task communication.
/// </summary>
[
    DataMemberAttribute,
    SysOperationControlVisibility(false)
]
public RecId parmEndBundle(RecId _endBundle = endBundle)
{
    endBundle = _endBundle;
    return endBundle;
}

/// <summary>
/// Unpacks and returns the Query object from the stored packed query string.
/// </summary>
public Query getQuery()
{
    return new Query(SysOperationHelper::base64Decode(packedQuery));
}

/// <summary>
/// Packs and stores the provided Query object.
/// </summary>
public void setQuery(Query _query)
{
    packedQuery = SysOperationHelper::base64Encode(_query.pack());
}

public static METCustRecurrenceInvoiceBatchPostContract construct()
{
    return new METCustRecurrenceInvoiceBatchPostContract();
}
